// A 2-second, 64 x 64 grey H.264 clip (8 frames, no sound, 1,537 bytes) for the offline video
// case of E2E-R (SPEC 14 1.57 TP-6). The fake provider's mp4File makes box headers only, with
// no samples, so Chromium cannot read its metadata (readyState stays 0, error 4); this clip
// decodes. Made with ffmpeg from a solid grey colour source; the encoder's own banner is kept
// (its name, version and options), no other metadata. It holds no picture, name or path from
// anywhere. SHA-256
// b7ebb83aeba1e72d052845fab573deb408bf216d39955f325c4e6af372e0fe83.
const BASE64 =
  ''

export const greyClip = (): Uint8Array => new Uint8Array(Buffer.from(BASE64, 'base64'))
